import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
const txt=(x,y,s,n=16)=>`<text x="${x}" y="${y}" fill="#f8f6f2" text-anchor="middle" font-family="sans-serif" font-size="${n}">${s}</text>`;
export function showEquilibrium(kind='reverse',t=null,state=null){const a=state?.a??20,b=state?.b??40;let art='',desc='',title='';if(kind==='dynamic'){title='Constant amounts. Continuing exchange.';desc=`Closed illustrative A/B model: A${a.toFixed(1)}, B${b.toFixed(1)}, forward exchange${(a*.2).toFixed(2)}, reverse${(b*.1).toFixed(2)} per step. Fractional values represent population amounts, not fractions of individual particles.`;art=`<rect x="35" y="55" width="370" height="200" rx="22" fill="#b7c8d611" stroke="#b7c8d6"/>${txt(120,95,'A',23)}${txt(320,95,'B',23)}<rect x="75" y="${230-a*2}" width="70" height="${a*2}" fill="#ed8b78"/><rect x="285" y="${230-b*2}" width="70" height="${b*2}" fill="#b7c8d6"/>${txt(110,275,a.toFixed(1),18)}${txt(320,275,b.toFixed(1),18)}${txt(220,135,'→ '+(a*.2).toFixed(2),16)}${txt(220,180,'← '+(b*.1).toFixed(2),16)}`;}else if(kind==='shift'){title='Predict the equilibrium response';desc='Balanced gaseous reaction N₂ plus3H₂ reversibly forms2NH₃; forward direction exothermic. Use imposed concentration, temperature or pressure information.';art=`${txt(220,60,'N₂ + 3H₂ ⇌ 2NH₃',27)}${txt(220,110,'Forward: exothermic',17)}<path d="M70 160H370M370 160l-12 -9m12 9l-12 9M370 215H70M70 215l12 -9m-12 9l12 9" stroke="#ed8b78" stroke-width="3"/>${txt(220,280,t?.title||'Change conditions · compare gas counts',15)}`;}else{title='A reaction can run both ways';desc='Blue hydrated copper sulfate can lose water on heating to form white anhydrous copper sulfate; adding water reverses the change. Energy transfers reverse direction.';art=`<circle cx="105" cy="135" r="48" fill="#9cbac3"/><circle cx="335" cy="135" r="48" fill="#f8f6f2"/>${txt(105,220,'Hydrated · blue',15)}${txt(335,220,'Anhydrous · white',15)}${txt(220,105,'Heat →',17)}${txt(220,165,'← Water',17)}${txt(220,280,'Energy transfer reverses',17)}`;}renderDiagram(title,t?.title||'Reversible reactions',`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${desc}">${art}</svg><p class="diagram-caption">${kind==='dynamic'?'Illustrative population-exchange model, not a measured reaction law.':'Symbolic representation; colours and energy arrows are schematic.'}</p>`,'REVERSIBLE SYSTEM · MODEL LIMITS APPLY');}
